// Behavioral oracle: grids generated by src/ must match the pre-refactor game.js exactly.
// Fixture provenance: git tag baseline-pre-refactor (generated by fixtures/generate-baseline.js).
// NEVER regenerate the fixture from src/.
import { test, expect, describe } from 'bun:test';
import { createHash } from 'node:crypto';
import { DIFF } from '../src/config.js';
import { createRound } from '../src/grid.js';
import { rnd } from '../src/rng.js';
import fixture from './fixtures/grids-baseline.json';

const rec = g => ({
  secret: g.secret, wLen: g.wLen, words: g.words.map(w => [w.text, w.col, w.start]),
  brackets: g.brackets.map(b => [b.col, b.start, b.str]), hexBase: g.hexBase,
  grid: g.cols.map(c => c.map(x => x.ch).join(''))
});

describe('full grids vs baseline', () => {
  for (const [key, seeds] of Object.entries(fixture.full)) {
    for (const [seed, exp] of Object.entries(seeds)) {
      test(`${key} seed ${seed}`, () => {
        const { game, nextSeed } = createRound(DIFF[key], +seed);
        const tail = [1, 2, 3, 4, 5].map(() => rnd());
        expect({ ...rec(game), next: nextSeed, tail }).toEqual(exp);
        expect(game.seed).toBe(+seed);
      });
    }
  }
});

describe('forced relax path vs baseline', () => {
  const { minW, maxW, base, seeds } = fixture.relax;
  const diff = { ...DIFF[base], minW, maxW };
  for (const [seed, exp] of Object.entries(seeds)) {
    test('seed ' + seed, () => {
      const { game, nextSeed } = createRound(diff, +seed);
      const tail = [1, 2, 3, 4, 5].map(() => rnd());
      const { tryGridCalls, relaxCalls, ...expected } = exp;
      expect(relaxCalls).toBeGreaterThan(0);   // baseline really took the relax path
      expect({ ...rec(game), next: nextSeed, tail }).toEqual(expected);
    });
  }
});

describe('hashes over seeds 0..299', () => {
  for (const key of Object.keys(fixture.hashes)) {
    test(key, () => {
      const h = createHash('sha256');
      for (let seed = 0; seed < 300; seed++) {
        const { game, nextSeed } = createRound(DIFF[key], seed);
        const { secret, wLen, words, brackets, hexBase, grid } = rec(game);
        h.update(JSON.stringify({ secret, wLen, words, brackets, hexBase, grid, next: nextSeed }));
      }
      expect(h.digest('hex')).toBe(fixture.hashes[key]);
    });
  }
});
